package com.tencent.shadow.core.runtime;import android.content.*;public class ShadowService extends ContextWrapper {Context application;public Context received;public ShadowService(Context app){super(app);application=app;}public Context getApplicationContext(){return application;}public final void setHostContextAsBase(Context c){attachBaseContext(c);}protected void attachBaseContext(Context c){received=c;if(c.getApplicationContext()!=application)throw new AssertionError("attach received host application");base=c;}}